using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Mail.Domain;

public sealed class MailDomain : ITenantEntity { private MailDomain() { } public MailDomain(Guid municipalityId, string domain) { Id = Guid.NewGuid(); MunicipalityId = municipalityId; Domain = domain.Trim().ToLowerInvariant(); State = "NOT_CONFIGURED"; CreatedAt = UpdatedAt = DateTimeOffset.UtcNow; } public Guid Id { get; private set; } public Guid MunicipalityId { get; private set; } public string Domain { get; private set; } = string.Empty; public string State { get; private set; } = string.Empty; public string? ExternalId { get; private set; } public DateTimeOffset CreatedAt { get; private set; } public DateTimeOffset UpdatedAt { get; private set; } public void ApplyProviderState(string state, string? externalId) { State = state.Trim(); ExternalId = externalId; UpdatedAt = DateTimeOffset.UtcNow; } }
